/// `"solaris"`, `"yuzu"`): the token `<name>-dark-<step>` or `<name>-light-<step>`. Panics if
/// the theme has no such token.
#[napi(js_name = "opencode_scale", skip_typescript)]
pub fn f_opencode_scale(a_name: Raw, a_dark: Raw, a_step: Raw) -> napi::Result<Raw> {
    conv::guard(|| {
        let a_name: String = conv::arg(a_name.0, "name")?;
        let a_dark: bool = conv::arg(a_dark.0, "dark")?;
        let a_step: u8 = conv::arg(a_step.0, "step")?;
        let out = conv::ToJs::to_js(rune_theme_opencode::scale(&a_name, a_dark, a_step))?;
        Ok(Raw(out))
    })
}

/// The kit tokens for one appearance, resolved for the blend mode of the window building the
/// view (`rune::theme::blends_srgb`): translucent tokens as authored when it blends in sRGB,
/// re-solved over `bg_base` when it blends in linear light. Get it in the view rather than
/// keeping it across a `Tx::set_srgb_blend`.
#[napi(js_name = "opencode_kit", skip_typescript)]
pub fn f_opencode_kit(a_dark: Raw) -> napi::Result<Raw> {
    conv::guard(|| {
        let a_dark: bool = conv::arg(a_dark.0, "dark")?;
        let out = conv::ToJs::to_js(rune_theme_opencode::kit(a_dark).clone())?;
        Ok(Raw(out))
    })
}

#[napi(js_name = "__C_opencode_GLYPHS", skip_typescript)]
pub fn c_opencode_GLYPHS() -> napi::Result<Raw> {
    conv::guard(|| Ok(Raw(conv::ToJs::to_js(rune_theme_opencode::GLYPHS.clone())?)))
}
